package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen1Test {

    @Test
    public void testEquals_SameReference() {
        String s = "test";
        assertTrue(StringUtils.equals(s, s));
    }

    @Test
    public void testEquals_BothNull() {
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_FirstNull() {
        assertFalse(StringUtils.equals(null, "test"));
    }

    @Test
    public void testEquals_SecondNull() {
        assertFalse(StringUtils.equals("test", null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        assertTrue(StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        assertFalse(StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_BothStrings_CaseSensitive() {
        assertFalse(StringUtils.equals("abc", "ABC"));
    }

    @Test
    public void testEquals_StringAndStringBuilder_Equal() {
        // Testing the branch where they are not both Strings
        // Note: The logic in the provided method uses cs1.length() >= cs2.length() 
        // and regionMatches(cs1, false, 0, cs2, 0, cs1.length())
        // This implies that if cs1 is longer than cs2, it will return false 
        // unless the regionMatches logic handles the length mismatch.
        // However, the code says: cs1.length() >= cs2.length() && regionMatches(cs1, ..., cs2, ..., cs1.length())
        // If cs1.length() > cs2.length(), regionMatches will likely throw IndexOutOfBounds 
        // or return false depending on CharSequenceUtils implementation.

        StringBuilder sb = new StringBuilder("abc");
        assertTrue(StringUtils.equals("abc", sb));
    }

    @Test
    public void testEquals_StringBuilderAndString_Equal() {
        StringBuilder sb = new StringBuilder("abc");
        assertTrue(StringUtils.equals(sb, "abc"));
    }

    @Test
    public void testEquals_DifferentLengths_Cs1Longer() {
        // This tests the branch: cs1.length() >= cs2.length()
        // If cs1 is "abcd" and cs2 is "abc", length check passes.
        // But regionMatches(cs1, false, 0, cs2, 0, 4) will attempt to read 4 chars from cs2 (length 3)
        // This tests the logic boundary.
        String cs1 = "abcd";
        String cs2 = "abc";
        // According to the code: cs1.length() (4) >= cs2.length() (3) is true.
        // Then it calls regionMatches(cs1, false, 0, cs2, 0, 4).
        // Most implementations of regionMatches return false if the requested length exceeds the source length.
        assertFalse(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_DifferentLengths_Cs2Longer() {
        // This tests the branch where cs1.length() < cs2.length()
        String cs1 = "abc";
        String cs2 = "abcd";
        assertFalse(StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_StringBuilderDifferentContent() {
        StringBuilder sb = new StringBuilder("abd");
        assertFalse(StringUtils.equals("abc", sb));
    }
}
